import BreadcrumbEight from "../components/BreadcrumbEight";
import Contact from "../components/Contact";
import FooterOne from "../components/FooterOne";
import SecondaryFooter from "../components/SecondaryFooter";
import HeaderOne from "../components/HeaderOne";
import Preloader from "../helper/Preloader";
import { SEO } from "../utils/SEO";
const ContactPage = () => {
  const can = window.location.href;

  return (
    <>
    <SEO
        title="4ceps | Contact Us – Healthcare Support & Customer Care"
        description="Contact 4ceps for healthcare services, appointments, or general inquiries. Our support team is ready to assist you quickly and easily."
        url={can}
      />
      {/* Preloader */}
      <Preloader />

      {/* HeaderOne */}
      <HeaderOne />

      {/* BreadcrumbEight */}
      <BreadcrumbEight />

      {/* Contact */}
      <Contact />

      <SecondaryFooter />

      {/* FooterOne */}
      <FooterOne />
    </>
  );
};

export default ContactPage;
